insert into public.sales_scripts (industry, label, sort, script) values ('accountants', 'רואי חשבון', 1, '{"pitch": "איסוף מסמכים אוטומטי לפני כל דיווח מע\"מ: ווטסאפ ללקוחות עם קישור אישי, וחיווי למי עוד חסר.", "topic": "איסוף המסמכים למע\"מ", "goal": "פגישת זום של 15-20 דקות עם אדיר", "steps": [{"title": "פתיחה", "note": "קצר, חיובי ובקצב רגוע. מוודאים שמדברים עם בעל העסק.", "lines": ["היי, שלום, {name}?", "מדבר/ת {agent} מ-A.L Systems. אני רואה שאתה רואה חשבון, נכון?"], "replies": [{"label": "כן, זה אני", "tone": "ok", "say": "מעולה, אני אהיה קצר/ה, דקה וחצי."}, {"label": "לא נוח עכשיו", "tone": "later", "say": "אין בעיה. מתי יותר נוח שאחזור, אחר הצהריים או מחר בבוקר? (סמן \"לחזור\" עם מועד)"}, {"label": "זה לא הוא / היא", "tone": "later", "say": "תודה! עם מי כדאי לי לדבר על הנושא של המערכות במשרד, ומתי הכי נוח לתפוס אותו/ה? (רשום בהערות וסמן \"לחזור\")"}]}, {"title": "שאלת הכאב", "note": "שאלה אחת ושותקים. נותנים לו לדבר.", "lines": ["תגיד, לפני כל דיווח מע\"מ, איך אתם אוספים היום את המסמכים מהלקוחות? מישהו במשרד רודף אחריהם בטלפון ובוואטסאפ?"], "replies": [{"label": "כן, ידנית", "tone": "ok", "say": "כמו רוב המשרדים. וזה גם הרבה שיחות, וגם תמיד יש מישהו שמגיע ברגע האחרון, נכון?"}, {"label": "יש לנו מערכת", "tone": "ok", "say": "מצוין. ויוצא שעדיין צריך להזכיר ידנית למי שלא העלה? (אם כן, להמשיך. אם הכל אוטומטי, לעבור להתנגדות \"יש לנו מערכת\")"}, {"label": "לא מעניין אותי", "tone": "no", "say": "בסדר גמור, תודה על הזמן ויום טוב. (סמן \"לא מעוניין\")"}]}, {"title": "מה אנחנו עושים", "note": "משפט או שניים, לא הרצאה.", "lines": ["אנחנו A.L Systems, מתמחים בייעוץ עסקי מהצד הטכני ובונים למשרדים מערכות שחוסכות את העבודה הזו.", "לדוגמה: ב-1 לחודש בתקופת המע\"מ, כל הלקוחות שלך מקבלים אוטומטית ווטסאפ עם קישור אישי, ומעלים דרכו את המסמכים. אצלך הכל נכנס למערכת מסודר לפי לקוח, ואתה רואה בכל רגע למי עוד חסר ולמי צריך לעשות שיחה יזומה."], "replies": [{"label": "נשמע מעניין", "tone": "ok", "say": "מעולה, אז בוא נקבע לך הדגמה קצרה."}, {"label": "שואל שאלות", "tone": "ok", "say": "שאלה מצוינת, ובדיוק בשביל זה הפגישה: אדיר יראה לך את זה חי ויענה על הכל. (לעבור לקביעה)"}]}, {"title": "קביעת הפגישה", "note": "המטרה היחידה של השיחה: פגישת זום של 15-20 דקות עם אדיר. תמיד שתי אפשרויות, לא \"מתי נוח לך?\".", "lines": ["אז בוא נקבע 15 דקות בזום, אדיר יראה לך הדגמה חיה על {topic}. מתאים לך {day1} או {day2}?", "מעולה. אני שולח לך קישור לזום בוואטסאפ למספר הזה. זה המספר הנכון?"], "replies": [{"label": "קבע מועד", "tone": "ok", "say": "רושם: {day}, בשעה {hour}. תקבל קישור לזום בוואטסאפ, ויום לפני תזכורת. תודה {name}, נדבר! (סמן \"נקבעה פגישה\" עם התאריך והשעה)"}, {"label": "לא יודע מתי פנוי", "tone": "later", "say": "בסדר גמור. מתי נוח שאחזור אליך לקבוע, מחר בבוקר? (סמן \"לחזור\" עם מועד)"}, {"label": "לא מעוניין", "tone": "no", "say": "בסדר גמור, תודה על הזמן {name}. יום טוב! (סמן \"לא מעוניין\")"}]}], "objections": [{"q": "תשלח לי חומר במייל / בוואטסאפ", "a": "בשמחה, אני שולח. רק שתדע, אין לנו חוברת מכירה כללית, כי כל מערכת נבנית לפי איך שהמשרד עובד. בגלל זה הצעתי 15 דקות בזום: אדיר מראה לך הדגמה חיה ואתה מחליט אם זה רלוונטי. מתי נוח לך, {day1} או {day2}?"}, {"q": "אין לי זמן עכשיו", "a": "לגמרי מבין, ובגלל זה אני לא גוזל לך זמן עכשיו. אני רק קובע 15 דקות בזום מתי שנוח לך. בוקר או אחר הצהריים יותר טוב?"}, {"q": "יש לנו כבר מערכת / תוכנה", "a": "מצוין, רוב מי שאנחנו עובדים איתם עובד עם תוכנה. אנחנו לא מחליפים אותה אלא בונים מה שחסר מסביב, כמו התזכורות והאיסוף בוואטסאפ, ומחברים לתוכנה שיש לך. שווה 15 דקות לראות אם יש משהו שיחסוך לך זמן?"}, {"q": "כמה זה עולה?", "a": "זה תלוי במה שבונים, כי כל מערכת מותאמת למשרד. בפגישה אדיר מראה הדגמה ונותן לך הערכה ברורה. הפגישה עצמה בלי עלות ובלי התחייבות."}, {"q": "מאיפה השגתם את המספר שלי?", "a": "מהפרטים הציבוריים של העסק שלך בגוגל. אם אתה מעדיף שלא נתקשר שוב, אני מוריד אותך מהרשימה עכשיו. (אם ביקש: סמן \"לא מעוניין\".)"}, {"q": "זה AI? אני לא סומך על זה", "a": "חלק מהדברים כן, אבל רובם אוטומציה פשוטה: הודעה שיוצאת בזמן, טופס שהלקוח ממלא, רשימה שמתעדכנת לבד. אתה רואה ומאשר כל דבר. בפגישה תראה בדיוק איך זה עובד."}], "guide": {"do": ["חיוך בקול, קצב רגוע ומשפטים קצרים.", "שאלה אחת ואז שותקים ומקשיבים.", "תמיד מציעים שני מועדים לפגישה.", "רושמים הערה קצרה אחרי כל שיחה."], "dont": ["לא מוכרים בטלפון ולא נותנים מחירים: המטרה היא פגישה.", "לא ממציאים לקוחות, נתונים או יכולות.", "מי שביקש שלא יתקשרו אליו מסמנים \"לא מעוניין\" ולא מתקשרים שוב.", "לא מתווכחים. התנגדות שנייה = מודים ומסיימים."]}}'::jsonb) on conflict (industry) do nothing;
insert into public.sales_scripts (industry, label, sort, script) values ('bookkeepers', 'הנהלת חשבונות ויועצי מס', 2, '{"pitch": "תזכורות ואיסוף מסמכים אוטומטי בוואטסאפ, ותמונת מצב של מי השלים ומי לא.", "topic": "איסוף המסמכים והתזכורות ללקוחות", "goal": "פגישת זום של 15-20 דקות עם אדיר", "steps": [{"title": "פתיחה", "note": "קצר, חיובי ובקצב רגוע. מוודאים שמדברים עם בעל העסק.", "lines": ["היי, שלום, {name}?", "מדבר/ת {agent} מ-A.L Systems. אני רואה שאתם עוסקים בהנהלת חשבונות, נכון?"], "replies": [{"label": "כן, זה אני", "tone": "ok", "say": "מעולה, אני אהיה קצר/ה, דקה וחצי."}, {"label": "לא נוח עכשיו", "tone": "later", "say": "אין בעיה. מתי יותר נוח שאחזור, אחר הצהריים או מחר בבוקר? (סמן \"לחזור\" עם מועד)"}, {"label": "זה לא הוא / היא", "tone": "later", "say": "תודה! עם מי כדאי לי לדבר על הנושא של המערכות במשרד, ומתי הכי נוח לתפוס אותו/ה? (רשום בהערות וסמן \"לחזור\")"}]}, {"title": "שאלת הכאב", "note": "שאלה אחת ושותקים.", "lines": ["כמה זמן הולך לכם כל חודש על לרדוף אחרי לקוחות שישלחו קבלות וחשבוניות?"], "replies": [{"label": "הרבה", "tone": "ok", "say": "זה מה שאנחנו שומעים מכולם. ויש תמיד את אלה ששולחים צילום מטושטש בוואטסאפ ברגע האחרון."}, {"label": "מסתדרים", "tone": "ok", "say": "יפה. ואם היה אפשר לחסוך את רוב השיחות האלה, היה שווה לך לראות איך?"}, {"label": "לא מעניין", "tone": "no", "say": "בסדר גמור, תודה ויום טוב. (סמן \"לא מעוניין\")"}]}, {"title": "מה אנחנו עושים", "note": "קצר.", "lines": ["אנחנו A.L Systems, בונים למשרדים מערכות שעושות את העבודה הזו לבד.", "כל לקוח מקבל בזמן שאתה קובע ווטסאפ עם קישור אישי להעלאת המסמכים. מי שלא העלה מקבל תזכורת אוטומטית, ואתה רואה רשימה מסודרת של מי השלים ומי לא."], "replies": [{"label": "מעניין", "tone": "ok", "say": "מעולה, בוא נקבע הדגמה קצרה."}, {"label": "שואל שאלות", "tone": "ok", "say": "בדיוק בשביל זה הפגישה, אדיר יראה לך את זה חי. (לעבור לקביעה)"}]}, {"title": "קביעת הפגישה", "note": "המטרה היחידה של השיחה: פגישת זום של 15-20 דקות עם אדיר. תמיד שתי אפשרויות, לא \"מתי נוח לך?\".", "lines": ["אז בוא נקבע 15 דקות בזום, אדיר יראה לך הדגמה חיה על {topic}. מתאים לך {day1} או {day2}?", "מעולה. אני שולח לך קישור לזום בוואטסאפ למספר הזה. זה המספר הנכון?"], "replies": [{"label": "קבע מועד", "tone": "ok", "say": "רושם: {day}, בשעה {hour}. תקבל קישור לזום בוואטסאפ, ויום לפני תזכורת. תודה {name}, נדבר! (סמן \"נקבעה פגישה\" עם התאריך והשעה)"}, {"label": "לא יודע מתי פנוי", "tone": "later", "say": "בסדר גמור. מתי נוח שאחזור אליך לקבוע, מחר בבוקר? (סמן \"לחזור\" עם מועד)"}, {"label": "לא מעוניין", "tone": "no", "say": "בסדר גמור, תודה על הזמן {name}. יום טוב! (סמן \"לא מעוניין\")"}]}], "objections": [{"q": "תשלח לי חומר במייל / בוואטסאפ", "a": "בשמחה, אני שולח. רק שתדע, אין לנו חוברת מכירה כללית, כי כל מערכת נבנית לפי איך שהמשרד עובד. בגלל זה הצעתי 15 דקות בזום: אדיר מראה לך הדגמה חיה ואתה מחליט אם זה רלוונטי. מתי נוח לך, {day1} או {day2}?"}, {"q": "אין לי זמן עכשיו", "a": "לגמרי מבין, ובגלל זה אני לא גוזל לך זמן עכשיו. אני רק קובע 15 דקות בזום מתי שנוח לך. בוקר או אחר הצהריים יותר טוב?"}, {"q": "יש לנו כבר מערכת / תוכנה", "a": "מצוין, רוב מי שאנחנו עובדים איתם עובד עם תוכנה. אנחנו לא מחליפים אותה אלא בונים מה שחסר מסביב, כמו התזכורות והאיסוף בוואטסאפ, ומחברים לתוכנה שיש לך. שווה 15 דקות לראות אם יש משהו שיחסוך לך זמן?"}, {"q": "כמה זה עולה?", "a": "זה תלוי במה שבונים, כי כל מערכת מותאמת למשרד. בפגישה אדיר מראה הדגמה ונותן לך הערכה ברורה. הפגישה עצמה בלי עלות ובלי התחייבות."}, {"q": "מאיפה השגתם את המספר שלי?", "a": "מהפרטים הציבוריים של העסק שלך בגוגל. אם אתה מעדיף שלא נתקשר שוב, אני מוריד אותך מהרשימה עכשיו. (אם ביקש: סמן \"לא מעוניין\".)"}, {"q": "זה AI? אני לא סומך על זה", "a": "חלק מהדברים כן, אבל רובם אוטומציה פשוטה: הודעה שיוצאת בזמן, טופס שהלקוח ממלא, רשימה שמתעדכנת לבד. אתה רואה ומאשר כל דבר. בפגישה תראה בדיוק איך זה עובד."}], "guide": {"do": ["חיוך בקול, קצב רגוע ומשפטים קצרים.", "שאלה אחת ואז שותקים ומקשיבים.", "תמיד מציעים שני מועדים לפגישה.", "רושמים הערה קצרה אחרי כל שיחה."], "dont": ["לא מוכרים בטלפון ולא נותנים מחירים: המטרה היא פגישה.", "לא ממציאים לקוחות, נתונים או יכולות.", "מי שביקש שלא יתקשרו אליו מסמנים \"לא מעוניין\" ולא מתקשרים שוב.", "לא מתווכחים. התנגדות שנייה = מודים ומסיימים."]}}'::jsonb) on conflict (industry) do nothing;
insert into public.sales_scripts (industry, label, sort, script) values ('insurance', 'סוכני ביטוח', 3, '{"pitch": "CRM לסוכנות: תזכורות חידוש פוליסות, איסוף מסמכים בוואטסאפ ומעקב אחרי כל לקוח.", "topic": "ניהול הלקוחות והתזכורות לחידושים", "goal": "פגישת זום של 15-20 דקות עם אדיר", "steps": [{"title": "פתיחה", "note": "קצר, חיובי ובקצב רגוע. מוודאים שמדברים עם בעל העסק.", "lines": ["היי, שלום, {name}?", "מדבר/ת {agent} מ-A.L Systems. אני רואה שאתה סוכן ביטוח, נכון?"], "replies": [{"label": "כן, זה אני", "tone": "ok", "say": "מעולה, אני אהיה קצר/ה, דקה וחצי."}, {"label": "לא נוח עכשיו", "tone": "later", "say": "אין בעיה. מתי יותר נוח שאחזור, אחר הצהריים או מחר בבוקר? (סמן \"לחזור\" עם מועד)"}, {"label": "זה לא הוא / היא", "tone": "later", "say": "תודה! עם מי כדאי לי לדבר על הנושא של המערכות במשרד, ומתי הכי נוח לתפוס אותו/ה? (רשום בהערות וסמן \"לחזור\")"}]}, {"title": "שאלת הכאב", "note": "שאלה אחת ושותקים.", "lines": ["איך אתה עוקב היום אחרי מועדי חידוש של פוליסות ואחרי לקוחות שצריך לחזור אליהם? אקסל, יומן, זיכרון?"], "replies": [{"label": "אקסל / יומן", "tone": "ok", "say": "וקורה שחידוש מתפספס או שלקוח הולך למתחרה כי לא חזרו אליו בזמן?"}, {"label": "יש תוכנה", "tone": "ok", "say": "יפה. והתזכורות ללקוחות עצמם יוצאות אוטומטית, או שזה עדיין טלפונים?"}, {"label": "לא מעניין", "tone": "no", "say": "בסדר גמור, תודה ויום טוב. (סמן \"לא מעוניין\")"}]}, {"title": "מה אנחנו עושים", "note": "קצר.", "lines": ["אנחנו A.L Systems, בונים לסוכנויות מערכת ניהול לקוחות שמותאמת בדיוק לאיך שאתה עובד.", "המערכת מזכירה לך ולשלוח ללקוח לפני כל חידוש, אוספת ממנו מסמכים בוואטסאפ עם קישור אישי, ואתה רואה בכל רגע מה פתוח אצל כל לקוח."], "replies": [{"label": "מעניין", "tone": "ok", "say": "מעולה, בוא נקבע הדגמה קצרה."}, {"label": "שואל שאלות", "tone": "ok", "say": "בדיוק בשביל זה הפגישה. (לעבור לקביעה)"}]}, {"title": "קביעת הפגישה", "note": "המטרה היחידה של השיחה: פגישת זום של 15-20 דקות עם אדיר. תמיד שתי אפשרויות, לא \"מתי נוח לך?\".", "lines": ["אז בוא נקבע 15 דקות בזום, אדיר יראה לך הדגמה חיה על {topic}. מתאים לך {day1} או {day2}?", "מעולה. אני שולח לך קישור לזום בוואטסאפ למספר הזה. זה המספר הנכון?"], "replies": [{"label": "קבע מועד", "tone": "ok", "say": "רושם: {day}, בשעה {hour}. תקבל קישור לזום בוואטסאפ, ויום לפני תזכורת. תודה {name}, נדבר! (סמן \"נקבעה פגישה\" עם התאריך והשעה)"}, {"label": "לא יודע מתי פנוי", "tone": "later", "say": "בסדר גמור. מתי נוח שאחזור אליך לקבוע, מחר בבוקר? (סמן \"לחזור\" עם מועד)"}, {"label": "לא מעוניין", "tone": "no", "say": "בסדר גמור, תודה על הזמן {name}. יום טוב! (סמן \"לא מעוניין\")"}]}], "objections": [{"q": "תשלח לי חומר במייל / בוואטסאפ", "a": "בשמחה, אני שולח. רק שתדע, אין לנו חוברת מכירה כללית, כי כל מערכת נבנית לפי איך שהמשרד עובד. בגלל זה הצעתי 15 דקות בזום: אדיר מראה לך הדגמה חיה ואתה מחליט אם זה רלוונטי. מתי נוח לך, {day1} או {day2}?"}, {"q": "אין לי זמן עכשיו", "a": "לגמרי מבין, ובגלל זה אני לא גוזל לך זמן עכשיו. אני רק קובע 15 דקות בזום מתי שנוח לך. בוקר או אחר הצהריים יותר טוב?"}, {"q": "יש לנו כבר מערכת / תוכנה", "a": "מצוין, רוב מי שאנחנו עובדים איתם עובד עם תוכנה. אנחנו לא מחליפים אותה אלא בונים מה שחסר מסביב, כמו התזכורות והאיסוף בוואטסאפ, ומחברים לתוכנה שיש לך. שווה 15 דקות לראות אם יש משהו שיחסוך לך זמן?"}, {"q": "כמה זה עולה?", "a": "זה תלוי במה שבונים, כי כל מערכת מותאמת למשרד. בפגישה אדיר מראה הדגמה ונותן לך הערכה ברורה. הפגישה עצמה בלי עלות ובלי התחייבות."}, {"q": "מאיפה השגתם את המספר שלי?", "a": "מהפרטים הציבוריים של העסק שלך בגוגל. אם אתה מעדיף שלא נתקשר שוב, אני מוריד אותך מהרשימה עכשיו. (אם ביקש: סמן \"לא מעוניין\".)"}, {"q": "זה AI? אני לא סומך על זה", "a": "חלק מהדברים כן, אבל רובם אוטומציה פשוטה: הודעה שיוצאת בזמן, טופס שהלקוח ממלא, רשימה שמתעדכנת לבד. אתה רואה ומאשר כל דבר. בפגישה תראה בדיוק איך זה עובד."}], "guide": {"do": ["חיוך בקול, קצב רגוע ומשפטים קצרים.", "שאלה אחת ואז שותקים ומקשיבים.", "תמיד מציעים שני מועדים לפגישה.", "רושמים הערה קצרה אחרי כל שיחה."], "dont": ["לא מוכרים בטלפון ולא נותנים מחירים: המטרה היא פגישה.", "לא ממציאים לקוחות, נתונים או יכולות.", "מי שביקש שלא יתקשרו אליו מסמנים \"לא מעוניין\" ולא מתקשרים שוב.", "לא מתווכחים. התנגדות שנייה = מודים ומסיימים."]}}'::jsonb) on conflict (industry) do nothing;
