insert into public.sales_scripts (industry, label, sort, script) values ('clinics', 'קליניקות ומרפאות', 5, '{"pitch": "תזכורות תורים בוואטסאפ, אישור הגעה ופחות ביטולים ברגע האחרון.", "topic": "זימון התורים והתזכורות", "goal": "פגישת זום של 15-20 דקות עם אדיר", "steps": [{"title": "פתיחה", "note": "קצר, חיובי ובקצב רגוע. מוודאים שמדברים עם בעל העסק.", "lines": ["היי, שלום, {name}?", "מדבר/ת {agent} מ-A.L Systems. אני מבין שיש לך קליניקה, נכון?"], "replies": [{"label": "כן, זה אני", "tone": "ok", "say": "מעולה, אני אהיה קצר/ה, דקה וחצי."}, {"label": "לא נוח עכשיו", "tone": "later", "say": "אין בעיה. מתי יותר נוח שאחזור, אחר הצהריים או מחר בבוקר? (סמן \"לחזור\" עם מועד)"}, {"label": "זה לא הוא / היא", "tone": "later", "say": "תודה! עם מי כדאי לי לדבר על הנושא של המערכות במשרד, ומתי הכי נוח לתפוס אותו/ה? (רשום בהערות וסמן \"לחזור\")"}]}, {"title": "שאלת הכאב", "note": "שאלה אחת ושותקים.", "lines": ["יוצא לכם שמטופלים לא מגיעים לתור, או מבטלים ברגע האחרון?"], "replies": [{"label": "כן, קורה", "tone": "ok", "say": "וכל תור כזה הוא שעה שהלכה. מי אצלכם עושה היום את התזכורות, ידנית?"}, {"label": "כמעט לא", "tone": "ok", "say": "יפה מאוד. ואיך מתנהלים זימון התורים והטפסים לפני טיפול, הכל ידני?"}, {"label": "לא מעניין", "tone": "no", "say": "בסדר גמור, תודה ויום טוב. (סמן \"לא מעוניין\")"}]}, {"title": "מה אנחנו עושים", "note": "קצר.", "lines": ["אנחנו A.L Systems, בונים לקליניקות מערכות שעושות את זה לבד.", "יום לפני כל תור המטופל מקבל ווטסאפ ומאשר הגעה בלחיצה. מי שמבטל משחרר את התור, ואתם רואים מראש מי מגיע."], "replies": [{"label": "מעניין", "tone": "ok", "say": "מעולה, בוא נקבע הדגמה קצרה."}, {"label": "שואל שאלות", "tone": "ok", "say": "בדיוק בשביל זה הפגישה. (לעבור לקביעה)"}]}, {"title": "קביעת הפגישה", "note": "המטרה היחידה של השיחה: פגישת זום של 15-20 דקות עם אדיר. תמיד שתי אפשרויות, לא \"מתי נוח לך?\".", "lines": ["אז בוא נקבע 15 דקות בזום, אדיר יראה לך הדגמה חיה על {topic}. מתאים לך {day1} או {day2}?", "מעולה. אני שולח לך קישור לזום בוואטסאפ למספר הזה. זה המספר הנכון?"], "replies": [{"label": "קבע מועד", "tone": "ok", "say": "רושם: {day}, בשעה {hour}. תקבל קישור לזום בוואטסאפ, ויום לפני תזכורת. תודה {name}, נדבר! (סמן \"נקבעה פגישה\" עם התאריך והשעה)"}, {"label": "לא יודע מתי פנוי", "tone": "later", "say": "בסדר גמור. מתי נוח שאחזור אליך לקבוע, מחר בבוקר? (סמן \"לחזור\" עם מועד)"}, {"label": "לא מעוניין", "tone": "no", "say": "בסדר גמור, תודה על הזמן {name}. יום טוב! (סמן \"לא מעוניין\")"}]}], "objections": [{"q": "תשלח לי חומר במייל / בוואטסאפ", "a": "בשמחה, אני שולח. רק שתדע, אין לנו חוברת מכירה כללית, כי כל מערכת נבנית לפי איך שהמשרד עובד. בגלל זה הצעתי 15 דקות בזום: אדיר מראה לך הדגמה חיה ואתה מחליט אם זה רלוונטי. מתי נוח לך, {day1} או {day2}?"}, {"q": "אין לי זמן עכשיו", "a": "לגמרי מבין, ובגלל זה אני לא גוזל לך זמן עכשיו. אני רק קובע 15 דקות בזום מתי שנוח לך. בוקר או אחר הצהריים יותר טוב?"}, {"q": "יש לנו כבר מערכת / תוכנה", "a": "מצוין, רוב מי שאנחנו עובדים איתם עובד עם תוכנה. אנחנו לא מחליפים אותה אלא בונים מה שחסר מסביב, כמו התזכורות והאיסוף בוואטסאפ, ומחברים לתוכנה שיש לך. שווה 15 דקות לראות אם יש משהו שיחסוך לך זמן?"}, {"q": "כמה זה עולה?", "a": "זה תלוי במה שבונים, כי כל מערכת מותאמת למשרד. בפגישה אדיר מראה הדגמה ונותן לך הערכה ברורה. הפגישה עצמה בלי עלות ובלי התחייבות."}, {"q": "מאיפה השגתם את המספר שלי?", "a": "מהפרטים הציבוריים של העסק שלך בגוגל. אם אתה מעדיף שלא נתקשר שוב, אני מוריד אותך מהרשימה עכשיו. (אם ביקש: סמן \"לא מעוניין\".)"}, {"q": "זה AI? אני לא סומך על זה", "a": "חלק מהדברים כן, אבל רובם אוטומציה פשוטה: הודעה שיוצאת בזמן, טופס שהלקוח ממלא, רשימה שמתעדכנת לבד. אתה רואה ומאשר כל דבר. בפגישה תראה בדיוק איך זה עובד."}], "guide": {"do": ["חיוך בקול, קצב רגוע ומשפטים קצרים.", "שאלה אחת ואז שותקים ומקשיבים.", "תמיד מציעים שני מועדים לפגישה.", "רושמים הערה קצרה אחרי כל שיחה."], "dont": ["לא מוכרים בטלפון ולא נותנים מחירים: המטרה היא פגישה.", "לא ממציאים לקוחות, נתונים או יכולות.", "מי שביקש שלא יתקשרו אליו מסמנים \"לא מעוניין\" ולא מתקשרים שוב.", "לא מתווכחים. התנגדות שנייה = מודים ומסיימים."]}}'::jsonb) on conflict (industry) do nothing;
